INSERT INTO payments VALUES (101, 1, 250.00);

CREATE OR REPLACE FUNCTION add_payment(p_id int, p_account int, p_amount numeric)
RETURNS text
LANGUAGE plpgsql
AS $$
BEGIN
  INSERT INTO payments (payment_id, account_id, amount)
  VALUES (p_id, p_account, p_amount);
  RETURN 'payment ' || p_id || ' saved';
EXCEPTION
  WHEN unique_violation THEN
    RETURN 'payment ' || p_id || ' already exists';
  WHEN foreign_key_violation THEN
    RETURN 'account ' || p_account || ' does not exist';
END;
$$;

SELECT add_payment(102, 1, 400.00);
SELECT add_payment(101, 1, 400.00);
SELECT add_payment(103, 99, 50.00);

CREATE OR REPLACE FUNCTION withdraw(p_account int, p_amount numeric)
RETURNS text
LANGUAGE plpgsql
AS $$
DECLARE
  v_steps int := 0;
BEGIN
  INSERT INTO audit_log (note)
  VALUES ('withdraw ' || p_amount || ' from account ' || p_account);

  BEGIN
    UPDATE accounts SET balance = balance - p_amount
     WHERE account_id = p_account;
    v_steps := v_steps + 1;

    INSERT INTO payments (payment_id, account_id, amount)
    VALUES (900 + p_account, p_account, -p_amount);
    v_steps := v_steps + 1;
  EXCEPTION
    WHEN OTHERS THEN
      RETURN format('failed after %s step(s): SQLSTATE %s, %s',
                    v_steps, SQLSTATE, SQLERRM);
  END;

  RETURN 'withdrawn ' || p_amount;
END;
$$;

SELECT withdraw(2, 1000.00);
SELECT withdraw(3, 200.00);
SELECT withdraw(3, 200.00);

CREATE OR REPLACE FUNCTION add_payment_logged(p_id int, p_account int, p_amount numeric)
RETURNS boolean
LANGUAGE plpgsql
AS $$
DECLARE
  v_state      text;
  v_constraint text;
  v_table      text;
  v_message    text;
  v_detail     text;
  v_context    text;
BEGIN
  INSERT INTO payments (payment_id, account_id, amount)
  VALUES (p_id, p_account, p_amount);
  RETURN true;
EXCEPTION
  WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
      v_state      = RETURNED_SQLSTATE,
      v_constraint = CONSTRAINT_NAME,
      v_table      = TABLE_NAME,
      v_message    = MESSAGE_TEXT,
      v_detail     = PG_EXCEPTION_DETAIL,
      v_context    = PG_EXCEPTION_CONTEXT;

    INSERT INTO error_log (payment_id, sql_state, constraint_name, message)
    VALUES (p_id, v_state, v_constraint, v_message);

    RAISE NOTICE 'table=%, detail=%', v_table, v_detail;
    RAISE NOTICE 'context=%', v_context;
    RETURN false;
END;
$$;

SELECT add_payment_logged(104, 7, 75.00);
SELECT add_payment_logged(105, 2, 12345678901.50);

CREATE OR REPLACE PROCEDURE transfer(p_from int, p_to int, p_amount numeric)
LANGUAGE plpgsql
AS $$
DECLARE
  v_balance numeric;
BEGIN
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'transfer amount must be positive, got %', p_amount
      USING ERRCODE = 'invalid_parameter_value';
  END IF;

  SELECT balance INTO v_balance
    FROM accounts WHERE account_id = p_from FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'account % not found', p_from
      USING ERRCODE = 'no_data_found';
  END IF;

  IF v_balance < p_amount THEN
    RAISE EXCEPTION 'insufficient funds in account %', p_from
      USING ERRCODE = 'SQ001',
            DETAIL  = format('balance %s, requested %s', v_balance, p_amount),
            HINT    = 'Reduce the amount or top up the account first.';
  END IF;

  UPDATE accounts SET balance = balance - p_amount WHERE account_id = p_from;
  UPDATE accounts SET balance = balance + p_amount WHERE account_id = p_to;
END;
$$;

CALL transfer(2, 1, 500.00);
CALL transfer(1, 2, -5);
CALL transfer(42, 2, 10);

DO $$
BEGIN
  CALL transfer(2, 3, 9999.00);
EXCEPTION
  WHEN SQLSTATE 'SQ001' THEN
    RAISE NOTICE 'caught: %', SQLERRM;
END;
$$;

CREATE OR REPLACE FUNCTION add_payment_strict(p_id int, p_account int, p_amount numeric)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
  INSERT INTO payments (payment_id, account_id, amount)
  VALUES (p_id, p_account, p_amount);
EXCEPTION
  WHEN OTHERS THEN
    INSERT INTO error_log (payment_id, sql_state, message)
    VALUES (p_id, SQLSTATE, SQLERRM);
    RAISE;
END;
$$;

SELECT count(*) FROM error_log;
