CREATE OR REPLACE PROCEDURE load_payments()
LANGUAGE plpgsql
AS $$
DECLARE
  r      record;
  v_ok   int := 0;
  v_bad  int := 0;
BEGIN
  FOR r IN SELECT * FROM payment_staging ORDER BY payment_id LOOP
    BEGIN
      INSERT INTO payments (payment_id, account_id, amount)
      VALUES (r.payment_id, r.account_id, r.amount);
      v_ok := v_ok + 1;
    EXCEPTION
      WHEN unique_violation OR foreign_key_violation
           OR numeric_value_out_of_range THEN
        INSERT INTO error_log (payment_id, sql_state, message)
        VALUES (r.payment_id, SQLSTATE, SQLERRM);
        v_bad := v_bad + 1;
    END;
  END LOOP;
  RAISE NOTICE 'loaded %, rejected %', v_ok, v_bad;
END;
$$;

CALL load_payments();

DO $$
BEGIN
  INSERT INTO audit_log (note) VALUES ('raw commit test');
  COMMIT;
EXCEPTION
  WHEN division_by_zero THEN
    NULL;
END;
$$;

SET statement_timeout = '1s';
DO $$
BEGIN
  PERFORM pg_sleep(5);
EXCEPTION
  WHEN OTHERS THEN
    RAISE NOTICE 'caught: %', SQLERRM;
END;
$$;
RESET statement_timeout;

CREATE OR REPLACE FUNCTION owner_of(p_account int)
RETURNS text
LANGUAGE plpgsql
AS $$
DECLARE
  v_owner text;
BEGIN
  SELECT owner_name INTO STRICT v_owner
    FROM accounts WHERE account_id = p_account;
  RETURN v_owner;
EXCEPTION
  WHEN no_data_found THEN
    RETURN 'no such account';
END;
$$;

SELECT owner_of(1), owner_of(42);

